DROP TABLE IF EXISTS `billing_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `billing_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint(20) unsigned NOT NULL,
  `subscription_plan_id` bigint(20) unsigned DEFAULT NULL,
  `action` enum('trial_started','plan_activated','plan_renewed','plan_upgraded','plan_downgraded','plan_suspended','plan_cancelled','plan_extended','payment_received') NOT NULL,
  `amount_xaf` int(10) unsigned NOT NULL DEFAULT 0,
  `effective_from` timestamp NULL DEFAULT NULL,
  `effective_until` timestamp NULL DEFAULT NULL,
  `payment_reference` varchar(191) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `performed_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `billing_records_school_id_foreign` (`school_id`),
  KEY `billing_records_subscription_plan_id_foreign` (`subscription_plan_id`),
  KEY `billing_records_performed_by_foreign` (`performed_by`),
  CONSTRAINT `billing_records_performed_by_foreign` FOREIGN KEY (`performed_by`) REFERENCES `super_admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `billing_records_school_id_foreign` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE CASCADE,
  CONSTRAINT `billing_records_subscription_plan_id_foreign` FOREIGN KEY (`subscription_plan_id`) REFERENCES `subscription_plans` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

