--
-- Table structure for table `subscription_plans`
--

DROP TABLE IF EXISTS `subscription_plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `subscription_plans` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `slug` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `price_xaf` int(10) unsigned NOT NULL,
  `annual_price_xaf` int(10) unsigned DEFAULT NULL,
  `billing_cycle` enum('monthly','annual','custom') NOT NULL DEFAULT 'monthly',
  `max_students` int(10) unsigned DEFAULT NULL,
  `max_staff` int(10) unsigned DEFAULT NULL,
  `trial_days` smallint(5) unsigned NOT NULL DEFAULT 30,
  `transaction_fee_percent` decimal(5,2) NOT NULL DEFAULT 2.50,
